from cardio_1 import a, G

a('SOFA', [('S','Sequential'),('O','Organ'),('F','Failure'),('A','Assessment')], 'Score séquentiel de défaillance d’organe', '<p>Nommé à l’origine Sepsis-related Organ Failure Assessment, il évalue six fonctions : respiration, coagulation, foie, circulation, système nerveux central et rein. Dans Sepsis-3, une augmentation aiguë d’au moins deux points consécutive à une infection représente opérationnellement la dysfonction d’organe ; ce score ne démontre pas à lui seul sa cause.</p>', 'a41-sofa')
a('A41', [('A','chapitre des maladies infectieuses de la classification'),('41','catégorie des autres sepsis')], 'Catégorie A41 de la CIM-10-GM', '<p>Autres sepsis ou sepsis d’agent non précisé ; ne couvre pas à elle seule A40 (streptocoques) ni le code complémentaire R57.2 du choc septique.</p>')
a('A40', [('A','chapitre des maladies infectieuses de la classification'),('40','catégorie des sepsis streptococciques')], 'Catégorie A40 de la CIM-10-GM', '<p>Code de la classification pour les sepsis streptococciques, distinct de A41.</p>')
a('R57.2', [('R','chapitre des symptômes, signes et résultats anormaux'),('57.2','sous-catégorie du choc septique')], 'Code R57.2 du choc septique dans la CIM-10-GM', '<p>Code complémentaire selon les règles de la classification en vigueur ; son usage relève d’une documentation diagnostique et de règles de codage applicables au lieu de soins.</p>')
a('SIRS', [('S','Systemic'),('I','Inflammatory'),('R','Response'),('S','Syndrome')], 'Syndrome de réponse inflammatoire systémique', '<p>Des critères inflammatoires peuvent aider au dépistage, mais ne définissent pas à eux seuls le sepsis selon Sepsis-3.</p>')
a('Sepsis-3', [('Sepsis','nom international de la définition de sepsis'),('3','troisième consensus')], 'Troisième consensus international de définition du sepsis', '<p>Consensus publié en 2016 par Singer et collaborateurs : le sepsis est une dysfonction d’organe menaçant la vie, causée par une réponse dérégulée de l’hôte à une infection. L’augmentation aiguë du score SOFA d’au moins deux points consécutive à l’infection est sa représentation opérationnelle.</p>', 'a41-sepsis3')
# Corrections de fusion Claude — 26.09.2026
a('V1a', [('V','Vasopressine'),('1a','récepteur de sous-type 1a')], 'Récepteur V1a de la vasopressine', '<p>Récepteur couplé aux protéines G situé sur le muscle lisse vasculaire ; sa stimulation par la vasopressine (argipressine) provoque une vasoconstriction indépendante des récepteurs adrénergiques. À ne pas confondre avec la dérivation précordiale V1 de l’électrocardiogramme.</p>')
a('R57.0', [('R','chapitre des symptômes, signes et résultats anormaux'),('57.0','sous-catégorie du choc cardiogénique')], 'Code R57.0 du choc cardiogénique dans la CIM-10-GM', '<p>Code de la CIM-10-GM désignant le choc cardiogénique, c’est-à-dire une hypoperfusion due à une défaillance de la fonction de pompe du cœur ; distinct du choc hypovolémique (R57.1) et du choc septique (R57.2).</p>')
a('R57.1', [('R','chapitre des symptômes, signes et résultats anormaux'),('57.1','sous-catégorie du choc hypovolémique')], 'Code R57.1 du choc hypovolémique dans la CIM-10-GM', '<p>Code de la CIM-10-GM désignant le choc hypovolémique, c’est-à-dire une hypoperfusion due à une diminution du volume sanguin circulant ; distinct du choc cardiogénique (R57.0) et du choc septique (R57.2).</p>')
a('VASST', [('V','Vasopressin'),('A','And'),('S','Septic'),('S','Shock'),('T','Trial')], 'Essai VASST (2008)', '<p>Argipressine 0,01–0,03 unité internationale/min contre supplément de noradrénaline chez 778 patients en choc septique : mortalité à 28 jours 35,4 % contre 39,3 %, différence non significative.</p>')
a('ADRENAL', [('ADRENAL','nom d’essai arrangé à partir de « ADjunctive coRticosteroid trEatment iN criticAlly iLl patients with septic shock », non strictement lettre à lettre')], 'Essai ADRENAL (2018)', '<p>Hydrocortisone 200 mg/jour en perfusion continue pendant 7 jours au plus chez 3 800 patients ventilés en choc septique randomisés (3 658 analysés) : mortalité à 90 jours 27,9 % contre 28,8 % sous placebo, résolution plus rapide du choc (médiane 3 contre 4 jours).</p>')
a('APROCCHSS', [('A','Activated'),('PRO','PROtein'),('C','C'),('C','Corticosteroids'),('H','Human'),('S','Septic'),('S','Shock')], 'Essai APROCCHSS (2018)', '<p>Le titre développé est Activated Protein C and Corticosteroids for Human Septic Shock ; les mots de liaison and et for restent hors du découpage du sigle. Hydrocortisone 50 mg toutes les 6 heures et fludrocortisone 50 µg par jour pendant 7 jours chez 1 241 patients en choc septique : mortalité à 90 jours 43,0 % contre 49,1 % sous placebo.</p>')
a('SEPSISPAM', [('SEPSIS','sepsis'),('PAM','Pression Artérielle Moyenne')], 'Essai SEPSISPAM (2014)', '<p>Essai français : pression artérielle moyenne cible de 80–85 mmHg contre 65–70 mmHg chez 776 patients en choc septique, sans différence de mortalité à 28 jours (36,6 % contre 34,0 %).</p>')
a('MERINO', [('MERINO','nom d’essai tiré du titre « MEropenem versus piperacillin-tazobactam for definitive treatment of bloodstream infections due to ceftriaxone non-susceptible Escherichia coli and Klebsiella spp », non strictement lettre à lettre')], 'Essai MERINO (2018)', '<p>Pipéracilline/tazobactam contre méropénem dans les bactériémies à entérobactéries résistantes à la ceftriaxone : mortalité à 30 jours 12,3 % contre 3,7 %, non-infériorité non démontrée.</p>')
a('BLING', [('B','Beta'),('L','Lactam'),('IN','InfusioN'),('G','Group')], 'Essais BLING (Beta-Lactam InfusioN Group)', '<p>BLING III (2024) : perfusion continue contre intermittente de pipéracilline/tazobactam ou de méropénem chez 7 031 patients en sepsis ; mortalité à 90 jours 24,9 % contre 26,8 %, différence non significative ; guérison clinique plus fréquente.</p>')
a('Solu-Cortef', [('Solu-Cortef','nom commercial composé d’une hydrocortisone injectable, non une abréviation')], 'Solu-Cortef, hydrocortisone injectable', '<p>Succinate sodique d’hydrocortisone, substance sèche de 100 mg ou 250 mg avec 2 mL de solvant, pour injection ou perfusion intraveineuse. Indications suisses : choc dû à une insuffisance corticosurrénalienne ou choc réfractaire au traitement conventionnel en présence éventuelle d’une insuffisance corticosurrénalienne ; l’information professionnelle (Swissmedic 23533, octobre 2025) ne recommande pas l’emploi de routine dans le choc septique.</p>')
# Vérification en texte intégral — 26.09.2026
a('CLOVERS', [('C','Crystalloid'),('L','Liberal'),('O','Or'),('V','Vasopressors'),('E','Early'),('R','Resuscitation in'),('S','Sepsis')], 'Essai CLOVERS (2023)', '<p>Stratégie restrictive privilégiant les vasopresseurs contre stratégie libérale en solutés pendant 24 heures chez 1 563 adultes dont l’hypotension due au sepsis persistait après 1 à 3 litres : mortalité avant retour à domicile à 90 jours 14,0 % contre 14,9 %, différence non significative.</p>')
# Réécriture pédagogique de l’onglet Pathologie — 26.09.2026 (sources consignées dans audits/A41.md)
a('FiO₂', [('F','Fraction'),('i','inspirée'),('O₂','en Oxygène (dioxygène)')], 'Fraction inspirée en oxygène', '<p>Proportion d’oxygène dans le gaz inspiré : 0,21 à l’air ambiant, jusqu’à 1,0 en oxygène pur. Le rapport PaO₂/FiO₂ mesure l’oxygénation dans le score SOFA ; chez Mme R., 66 mmHg divisés par 0,21 donnent 314.</p>')
a('SOAP', [('S','Sepsis'),('O','Occurrence in'),('A','Acutely ill'),('P','Patients')], 'Étude SOAP (2006)', '<p>Étude de cohorte européenne menée en mai 2002 dans 198 unités de soins intensifs de 24 pays : 1 177 des 3 147 patients (37,4 %) avaient un sepsis. Le foyer était pulmonaire dans 68 % des cas et abdominal dans 22 % ; un bilan hydrique positif figurait parmi les plus forts facteurs pronostiques de décès.</p>')
a('BALANCE', [('B','Bacteremia'),('A','Antibiotic'),('L','Length'),('A','Actually'),('N','Needed for'),('C','Clinical'),('E','Effectiveness')], 'Essai BALANCE (2025)', '<p>Essai de non-infériorité chez 3 608 patients hospitalisés pour une bactériémie, dans 74 hôpitaux de 7 pays : 7 jours d’antibiotique n’étaient pas inférieurs à 14 jours (mortalité à 90 jours 14,5 % contre 16,1 %). L’essai excluait <i>Staphylococcus aureus</i>, l’immunodépression sévère et les foyers exigeant un traitement prolongé.</p>')
a('ANDROMEDA-SHOCK', [('ANDROMEDA-SHOCK','nom propre d’essai, non développé en sigle dans les publications consultées')], 'Essai ANDROMEDA-SHOCK (2019)', '<p>Essai randomisé de 424 patients en choc septique dans 28 unités de soins intensifs de 5 pays : une réanimation visant la normalisation du temps de recoloration capillaire, comparée à une réanimation guidée par le lactate, n’a pas réduit significativement la mortalité à 28 jours (34,9 % contre 43,4 %) et a réduit les défaillances d’organe à 72 heures.</p>', 'a41-sign-perfusion')
a('ANDROMEDA-SHOCK-2', [('ANDROMEDA-SHOCK','nom propre d’essai, non développé en sigle dans les publications consultées'),('2','deuxième essai')], 'Essai ANDROMEDA-SHOCK-2 (2025)', '<p>Essai randomisé de 1 501 patients en choc septique précoce dans 86 centres de 19 pays : une réanimation personnalisée guidée par le temps de recoloration capillaire a été supérieure aux soins usuels sur un critère hiérarchique associant mortalité, durée des suppléances vitales et durée de séjour (rapport de victoires de 1,16), surtout par une durée plus courte des suppléances.</p>', 'a41-sign-perfusion')
a('Ait-Oufella', [('Ait-Oufella','nom propre d’auteur, non une abréviation')], 'Ait-Oufella, premier auteur de l’étude du score de marbrures (2011)', '<p>Premier auteur de l’étude qui a décrit le score de marbrures de 0 à 5 dans le choc septique et montré sa valeur pronostique (<i>Intensive Care Medicine</i> 2011).</p>')
# Compléments du candidat A41 — 08.10.2026 ; contre-audit externe en attente.
a('PCT', [('PCT','abréviation conventionnelle de procalcitonine, un seul nom et non trois mots')], 'Procalcitonine', '<p>Précurseur de la calcitonine utilisé comme biomarqueur inflammatoire. Une valeur isolée ne confirme ni n’exclut le sepsis. Son évolution peut aider à décider l’arrêt d’un antibiotique avec l’évaluation clinique, un foyer contrôlé et une durée optimale incertaine.</p>', 'a41-pct')
a('PBP', [('P','Penicillin'),('B','Binding'),('P','Proteins')], 'Protéines liant les pénicillines', '<p>Protéines bactériennes dont certaines participent à la construction du peptidoglycane. Leur inhibition par une bêtalactamine fragilise la paroi d’une bactérie sensible ; une modification de cible peut participer à la résistance.</p>')
a('BLSE', [('B','Bêta-'),('L','Lactamases'),('S','Spectre'),('E','Étendu')], 'Bêtalactamases à spectre étendu', '<p>Enzymes capables d’hydrolyser plusieurs bêtalactamines, notamment des céphalosporines de troisième génération. La sensibilité du germe et le contexte de l’infection doivent être vérifiés ; ce sigle ne décrit pas à lui seul tous ses mécanismes de résistance.</p>')
a('SARM', [('S','Staphylococcus'),('A','Aureus'),('R','Résistant'),('M','Méticilline')], 'Staphylococcus aureus résistant à la méticilline', '<p>Phénotype de résistance associé à une protéine liant les pénicillines de moindre affinité pour de nombreuses bêtalactamines. La couverture probabiliste dépend du risque individuel, du foyer et de l’écologie locale.</p>')
a('AUC', [('A','Area'),('U','Under'),('C','Curve')], 'Aire sous la courbe des concentrations', '<p>Intégrale de la concentration d’un médicament en fonction du temps. Pour la vancomycine, son rapport à la concentration minimale inhibitrice aide à apprécier l’exposition ; l’interprétation dépend de la méthode de mesure, de l’indication et de la fonction rénale.</p>')
a('ESE', [('E','European'),('S','Society'),('E','Endocrinology')], 'Société européenne d’endocrinologie', '<p>Société savante coautrice des recommandations de 2024 sur l’insuffisance surrénalienne induite par les glucocorticoïdes.</p>')
a('EAU', [('E','European'),('A','Association'),('U','Urology')], 'Association européenne d’urologie', '<p>Société savante éditrice des recommandations sur les infections urologiques. Ses schémas concernent un foyer et un contexte définis ; ils ne s’appliquent pas automatiquement à tout sepsis.</p>')
a('XueBiJing', [('XueBiJing','nom propre d’une préparation injectable, non une abréviation')], 'Préparation injectable XueBiJing', '<p>La Surviving Sepsis Campaign 2026 suggère de ne pas utiliser cette préparation hors des juridictions où elle possède une autorisation réglementaire ; recommandation conditionnelle, certitude très faible. Cette mention ne démontre pas une autorisation en Suisse.</p>')
a('A48.3', [('A','chapitre des maladies infectieuses de la classification'),('48.3','sous-catégorie du syndrome de choc toxique')], 'Syndrome de choc toxique, code A48.3 de la CIM-10-GM 2024', '<p>Catégorie distincte du sepsis A41 et du choc septique R57.2. La notice BfArM 2024 exclut de cette rubrique le choc endotoxinique R57.8 et le sepsis A41.9 ; cette entrée de glossaire ne signifie pas que toutes les formes de choc toxique sont enseignées dans A41.</p>')
a('ProCESS', [('Pro','Protocolized'),('C','Care'),('E','Early'),('S','Septic'),('S','Shock')], 'Essai ProCESS (2014)', '<p>Protocolized Care for Early Septic Shock : essai multicentrique de 1 341 patients répartis entre trois stratégies de réanimation. Les soins protocolisés n’ont pas amélioré la mortalité à 60 jours par rapport aux soins usuels. Le registre NCT00510835 confirme le titre et le sigle ; le mot de liaison for reste hors du découpage.</p>')
a('ARISE', [('A','Australasian'),('R','Resuscitation'),('I','In'),('S','Sepsis'),('E','Evaluation')], 'Essai ARISE (2014)', '<p>Australasian Resuscitation In Sepsis Evaluation : essai de 1 600 patients avec choc septique précoce, comparant une réanimation guidée par objectifs aux soins usuels, sans réduction de mortalité à 90 jours. Le titre développé figure dans le registre NCT00975793.</p>')
a('ProMISe', [('Pro','Protocolised'),('M','Management'),('I','In'),('Se','Sepsis')], 'Essai ProMISe (2015)', '<p>Protocolised Management In Sepsis : essai de 1 260 patients, sans amélioration de mortalité à 90 jours par la réanimation selon des objectifs centraux imposés par rapport aux soins usuels. Le titre développé est celui du rapport original de 2015, identifiant PubMed 26597979 ; le résultat clinique est publié sous l’identifiant 25776532.</p>')
# Termes relevés lors du contrôle technique du candidat complet.
a('A32.7', [('A','chapitre des maladies infectieuses de la classification'),('32.7','sous-catégorie du sepsis à Listeria')], 'Sepsis à Listeria, code A32.7 de la CIM-10-GM 2024', '<p>Catégorie spécifique à la listériose systémique, distincte des autres sepsis A41. Sa mention ne certifie pas une couverture exhaustive de cette catégorie dans ce cours.</p>')
a('B37.7', [('B','chapitre des maladies infectieuses de la classification'),('37.7','sous-catégorie du sepsis à Candida')], 'Sepsis à Candida, code B37.7 de la CIM-10-GM 2024', '<p>Catégorie spécifique au sepsis à Candida, distincte des autres sepsis A41. Une stratégie antifongique dépend du contexte clinique et du risque individuel.</p>')
a('NEWS', [('N','National'),('E','Early'),('W','Warning'),('S','Score')], 'Score national d’alerte précoce', '<p>Score de détérioration physiologique. Il contribue à repérer un patient à réévaluer ; il ne démontre pas une infection et ne définit pas à lui seul le sepsis.</p>')
a('NEWS2', [('N','National'),('E','Early'),('W','Warning'),('S','Score'),('2','deuxième version')], 'Deuxième version du score national d’alerte précoce', '<p>Version révisée du score d’alerte précoce. Son interprétation suit le protocole de surveillance et les caractéristiques du patient, avec une évaluation clinique.</p>', 'a41-news2')
a('MEWS', [('M','Modified'),('E','Early'),('W','Warning'),('S','Score')], 'Score modifié d’alerte précoce', '<p>Score de détérioration physiologique distinct du NEWS2. Un score d’alerte organise une réponse clinique ; il ne remplace ni l’examen du patient ni le diagnostic de la cause.</p>')
a('CAPITA', [('C','Community'),('A','Acquired'),('P','Pneumonia'),('I','Immunization'),('T','Trial'),('A','Adults')], 'Essai CAPiTA de vaccination antipneumococcique (2015)', '<p>Community-Acquired Pneumonia Immunization Trial in Adults, habituellement écrit CAPiTA : essai du vaccin conjugué 13-valent chez des adultes âgés aux Pays-Bas. Il porte sur des critères pneumococciques définis et ne démontre pas la prévention de tout sepsis.</p>')
a('PCV13', [('P','Pneumococcal'),('C','Conjugate'),('V','Vaccine'),('13','treize sérotypes')], 'Vaccin pneumococcique conjugué 13-valent', '<p>Vaccin dirigé contre treize sérotypes de pneumocoque. Le nombre de valences et les recommandations nationales en vigueur doivent être distingués du vaccin étudié dans un essai historique.</p>')
a('SCCM', [('S','Society'),('C','Critical'),('C','Care'),('M','Medicine')], 'Society of Critical Care Medicine', '<p>Société savante éditrice avec l’ESICM des recommandations de la Surviving Sepsis Campaign. Les mots de liaison of restent hors du découpage.</p>')
a('SAPS', [('S','Stop'),('A','Antibiotics'),('P','Procalcitonin'),('S','Study')], 'Essai SAPS de guidage de l’arrêt des antibiotiques', '<p>Stop Antibiotics on Procalcitonin Guidance Study, titre confirmé par le registre NCT01139489. L’essai étudie un conseil d’arrêt guidé par la procalcitonine chez des adultes en soins intensifs ; il ne valide pas ce biomarqueur comme diagnostic isolé ni comme décision automatique de début d’antibiotique.</p>')
a('CHUV', [('C','Centre'),('H','Hospitalier'),('U','Universitaire'),('V','Vaudois')], 'Centre hospitalier universitaire vaudois', '<p>Institution hospitalière universitaire de Lausanne. Une plage analytique ou une procédure citée doit rester associée au document, à la méthode et à la matrice concernés.</p>')
a('USZ', [('U','Universitäts-'),('S','Spital'),('Z','Zürich')], 'Hôpital universitaire de Zurich', '<p>Universitätsspital Zürich. Les plages citées dans son catalogue concernent une méthode et une matrice précisées ; elles ne sont pas automatiquement les normes de tout laboratoire.</p>')
a('PAI-1', [('P','Plasminogen'),('A','Activator'),('I','Inhibitor'),('1','type 1')], 'Inhibiteur de l’activateur du plasminogène de type 1', '<p>Inhibe des activateurs du plasminogène et limite ainsi la formation de plasmine. Une augmentation peut participer à une réduction de fibrinolyse ; elle ne décrit pas à elle seule tout l’équilibre de coagulation du patient.</p>')
a('dL', [('d','déci-, facteur 0,1'),('L','litre')], 'Décilitre', '<p>Un décilitre correspond à 0,1 litre. Une concentration de 1 mg/dL correspond donc à 10 mg/L.</p>')
a('Garcia-Alvarez', [('Garcia-Alvarez','nom propre d’auteur, non une abréviation')], 'Garcia-Alvarez, auteur cité sur l’hyperlactatémie associée au sepsis', '<p>Nom de l’auteur de la revue citée de 2014. La nature de revue et les différences entre observations humaines et modèles expérimentaux restent précisées dans le texte.</p>')
a('Plasma-Lyte', [('Plasma-Lyte','nom commercial de solutions de perfusion, non une abréviation')], 'Famille de solutions de perfusion Plasma-Lyte', '<p>Nom commercial d’un cristalloïde équilibré. La présentation et sa composition doivent être vérifiées ; la mention d’un nom d’essai ne rend pas toutes les formulations interchangeables.</p>')
a('SMART', [('S','Solutions'),('M','Major'),('A','Adverse'),('R','Renal'),('T','Trial')], 'Essai SMART (2018)', '<p>Nom arrangé de Isotonic Solutions and Major Adverse Renal Events Trial. L’essai compare cristalloïdes équilibrés et solution saline en soins intensifs ; son critère principal est un composite rénal incluant le décès, et ne se confond pas avec une démonstration de gain de survie isolé.</p>')
a('BaSICS', [('BaSICS','nom arrangé de Balanced Solution Versus Saline in Intensive Care Study, non strictement un mot par lettre')], 'Essai BaSICS (2021)', '<p>Le registre NCT02875873 confirme le titre. La comparaison en soins intensifs n’a pas démontré de réduction de mortalité à 90 jours avec la solution équilibrée ; absence de différence significative ne signifie pas équivalence de toutes les situations.</p>')
a('PLUS', [('PLUS','nom arrangé de Plasma-Lyte 148 versUs Saline Study, non strictement un mot par lettre')], 'Essai PLUS (2022)', '<p>Le registre NCT02721654 confirme le titre. Cet essai en soins intensifs n’a pas démontré de réduction de mortalité ou d’atteinte rénale avec la solution équilibrée par rapport à la solution saline.</p>')
a('SAFE', [('S','Saline'),('A','Albumin'),('F','Fluid'),('E','Evaluation')], 'Essai SAFE (2004)', '<p>Saline versus Albumin Fluid Evaluation : comparaison de solution saline et d’albumine pour la réanimation en soins intensifs. Les résultats d’une population générale ne rendent pas ces solutions interchangeables dans toutes les situations particulières.</p>')
a('ALBIOS', [('ALB','ALBumin'),('I','Italian'),('O','Outcome'),('S','Sepsis')], 'Essai ALBIOS (2014)', '<p>ALBumin Italian Outcome Sepsis, titre confirmé par le registre NCT00707122. L’ajout d’albumine aux cristalloïdes n’a pas réduit significativement la mortalité globale ; un sous-groupe ne définit pas à lui seul une indication universelle.</p>')
a('DC', [('D','Débit'),('C','Cardiaque')], 'Débit cardiaque', '<p>Volume de sang éjecté par le cœur par unité de temps, souvent exprimé en L/min. Son augmentation ne démontre pas à elle seule la restauration de la perfusion de tous les organes.</p>')
a('PVC', [('P','Pression'),('V','Veineuse'),('C','Centrale')], 'Pression veineuse centrale', '<p>Pression mesurée dans la circulation veineuse centrale, exprimée ici en mmHg. Une valeur isolée ne prédit pas de façon fiable la réponse à un apport de liquide.</p>')
a('CaO₂', [('C','Contenu'),('a','artériel'),('O₂','dioxygène')], 'Contenu artériel en oxygène', '<p>Quantité d’oxygène par volume de sang artériel. Dans l’équation pédagogique du chapitre, elle est exprimée en mL/dL et dépend surtout de l’hémoglobine et de sa saturation ; la saturation seule ne décrit pas ce contenu.</p>')
a('DO₂', [('D','Delivery, apport'),('O₂','dioxygène')], 'Apport global en oxygène', '<p>Produit du débit cardiaque et du contenu artériel en oxygène, avec conversion des unités. Ce calcul global ne mesure ni la répartition entre organes ni l’extraction cellulaire d’oxygène.</p>')
